# Вариант А: логистика и магазины. Формат задачи см. build.py
V = 'A'
TASKS = [
dict(n=1, pts=0.5, title='Доставка в город', topics='if / elif / else, in',
 text='В окне уже заданы список `cities` и три фразы: `ok_msg`, `many_msg`, `other_msg`. Вводятся город и вес посылки в килограммах.\n\nЕсли город есть в списке `cities` и вес не больше 500, напечатайте `ok_msg`. Если город в списке, но вес больше 500, напечатайте `many_msg`. Если города нет в списке, напечатайте `other_msg`.\n\nПеременные уже заданы: их нужно напечатать, а не переписывать фразы руками.',
 fin='Первая строка — город, вторая — вес (целое число).', fout='Одна из трёх фраз.',
 pre="cities = ['Москва', 'Казань', 'Самара']\nok_msg = 'Доставим курьером'\nmany_msg = 'Разделим на несколько посылок'\nother_msg = 'Передадим партнёру'",
 inputs=[['Москва','300'],['Казань','500'],['Самара','501'],['Омск','100'],['Москва','1'],['омск','900']],
 sol="city = input()\nweight = int(input())\n\nif city in cities:\n    if weight <= 500:\n        print(ok_msg)\n    else:\n        print(many_msg)\nelse:\n    print(other_msg)\n",
 hint='Сначала проверьте город через `in`, и уже внутри сравнивайте вес. Не забудьте `int` для веса.',
 idea='Два условия вложены друг в друга: сначала «город в списке?», потом «вес не больше 500?».',
 steps=['`city = input()` читает строку, `weight = int(input())` читает вес и сразу делает его числом.','`city in cities` — проверка, что город входит в список.','Внутри — `weight <= 500`: «не больше 500» значит, что ровно 500 ещё подходит.','Печатаем **переменные** (`print(ok_msg)`), а не слова в кавычках: иначе выведется слово `ok_msg`.'],
 mist=['Забыли `int(...)`: сравнение строки с числом даст `TypeError`.','Написали `<` вместо `<=`: вес ровно 500 попадёт не в ту ветку.','Напечатали фразу руками (`print("Доставим курьером")`): на проверке она может отличаться.']),
dict(n=2, pts=1, title='Лёгкие товары', topics='while True, break, split, список',
 text='Вводятся строки вида `Название:вес` (вес в килограммах, целое число), пока не будет введено слово `END`.\n\nЕсли вес товара не больше 20, добавьте его название в список. В конце напечатайте этот список целиком.',
 fin='Строки `Название:вес`, последняя строка — `END`.', fout='Список названий в квадратных скобках, как печатает `print(список)`. Если подходящих нет — `[]`.',
 pre='',
 inputs=[['Ноутбук:25','Мышь:1','Кресло:20','END'],['END'],['Стол:50','Шкаф:80','END'],['Лампа:3','Книга:2','Кофе машина:12','END'],['Диван:21','Плед:1','END']],
 sol="light = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    name, weight = line.split(':')\n    if int(weight) <= 20:\n        light.append(name)\n\nprint(light)\n",
 hint='Список создайте до цикла. Строку режьте по двоеточию: `name, weight = line.split(":")`. Вес — строка, нужен `int`.',
 idea='Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.',
 steps=['`light = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.','`while True:` — читаем, пока сами не прервём.','Если строка равна `END` — `break`; разбирать её дальше не нужно.','`line.split(":")` даёт `["Мышь", "1"]`, `name, weight = ...` раскладывает на две переменные.','`int(weight) <= 20` — «не больше 20»; подходящее название кладём `append`.','`print(light)` печатает именно список со скобками и кавычками.'],
 mist=['Список создан внутри цикла — в конце останется только последний товар.','Не сделали `int(weight)`: сравнение `"25" <= 20` падает с `TypeError`.','Печатали названия по одному, а нужен список целиком.','Забыли `break`: программа «зависает» и ждёт строки дальше.'],
 trace='Ввод `Ноутбук:25`, `Мышь:1`, `Кресло:20`, `END`: Ноутбук — 25 больше 20, пропускаем; Мышь — 1, добавляем; Кресло — 20, добавляем (не больше!); `END` — выходим. Итог `[\'Мышь\', \'Кресло\']`.'),
dict(n=3, pts=0.5, title='Добавить участника', topics='split(", "), not in, append',
 text='В первой строке имена участников через «запятая + пробел». Во второй — имя нового участника.\n\nЕсли такого имени ещё нет в списке, добавьте его в конец. Напечатайте список.',
 fin='Первая строка — имена через `, `. Вторая — одно имя.', fout='Список имён в квадратных скобках.',
 pre='',
 inputs=[['Анна, Борис, Вера','Глеб'],['Анна, Борис','Борис'],['Ольга','Ольга'],['Игорь, Пётр','Анна']],
 sol="names = input().split(', ')\nnew_name = input()\n\nif new_name not in names:\n    names.append(new_name)\n\nprint(names)\n",
 hint='Разделитель — запятая **и пробел**: `.split(", ")`. Условие — `not in`.',
 idea='Разбиваем строку на список, проверяем наличие имени и добавляем только если его нет.',
 steps=['`input().split(", ")` разбивает строку по «запятая + пробел» сразу на список.','`not in` — «не входит». Если имени нет, делаем `append`.','Порядок не трогаем: новое имя встаёт в конец.','Печатаем весь список: `print(names)`.'],
 mist=['`split(",")` без пробела оставит у имён пробел в начале (`" Борис"`) — проверка `in` сломается.','Добавили имя без проверки — получили дубликат.','Забыли напечатать список после `if`.']),
dict(n=4, pts=1, title='Курьеры дешевле бюджета', topics='два списка, range(len())',
 text='Три строки: названия курьерских служб через пробел; цены доставки через пробел (по одной на службу, в том же порядке); бюджет.\n\nНапечатайте названия служб, у которых цена **строго меньше** бюджета, каждое с новой строки. Если таких нет, ничего не печатайте.',
 fin='Три строки: названия, цены, бюджет (целые числа).', fout='Названия по одному на строке или пустой вывод.',
 pre='',
 inputs=[['СДЭК Почта Боксберри','300 150 200','200'],['А Б В','10 10 10','10'],['Курьер Экспресс','50 500','1000'],['Один','5','6'],['Х Y Z','90 80 70','60']],
 sol="companies = input().split()\nprices = input().split()\nbudget = int(input())\n\nfor i in range(len(companies)):\n    if int(prices[i]) < budget:\n        print(companies[i])\n",
 hint='Два списка идут «параллельно»: у `companies[i]` цена `prices[i]`. Переберите номера `i` через `range(len(companies))`.',
 idea='Данные лежат в двух списках, связь между ними — одинаковый номер. Перебираем номера и сравниваем цену с бюджетом.',
 steps=['`input().split()` даёт списки **строк**, в том числе цены.','`range(len(companies))` — это номера 0, 1, 2, …','`int(prices[i])` — превращаем цену в число прямо в сравнении.','«Строго меньше» — это `<`. Пример с равными числами проверяет именно это.','`print(companies[i])` внутри цикла печатает каждую подходящую службу с новой строки.'],
 mist=['Сравнивали строку `prices[i]` с числом: `TypeError`.','Взяли `<=` вместо `<`: при цене, равной бюджету, службу напечатали зря.','`print` без отступа — печатается только после цикла и только последняя.'],
 trace='Ввод: службы `СДЭК Почта Боксберри`, цены `300 150 200`, бюджет 200. i=0: 300 не меньше 200 — пропуск; i=1: 150 меньше — печатаем `Почта`; i=2: 200 не меньше 200 — пропуск.'),
dict(n=5, pts=0.75, title='Общие товары двух складов', topics='множества, пересечение',
 text='Две строки: товары первого склада и товары второго склада (через пробел). Внутри строки названия не повторяются.\n\nНапечатайте, сколько товаров есть **на обоих** складах.',
 fin='Две строки названий через пробел.', fout='Одно число.',
 pre='',
 inputs=[['Чай Кофе Сахар','Кофе Мёд Сахар Соль'],['А Б','В Г'],['Х','Х'],['а б в г д','д г в б а']],
 sol="first = set(input().split())\nsecond = set(input().split())\n\nprint(len(first & second))\n",
 hint='«Есть в обоих» — пересечение множеств, знак `&`. `len` считает размер.',
 idea='Превращаем обе строки в множества и берём пересечение.',
 steps=['`set(input().split())` — слова строки в множество.','`first & second` оставляет только общие элементы.','`len(...)` считает, сколько их.'],
 mist=['Пересечение `&` перепутали с объединением `|` — получили всех, а не общих.','Сравнивали строки целиком, а не слова: нужен `split()`.']),
dict(n=6, pts=1.25, title='Курсы по выбору', topics='множества, объединение и пересечение',
 text='Три строки с названиями курсов через запятую **без пробела** (в названиях пробелы бывают): курсы, которые выбрала Аня; курсы, которые выбрал Борис; курсы, доступные в университете.\n\nНапечатайте, сколько курсов выбрала Аня **или** Борис (или оба) и при этом они есть в университете.',
 fin='Три строки, названия через запятую.', fout='Одно число.',
 pre='',
 inputs=[['Python,Статистика,Право','Python,История,Право','Python,Право,Музыка'],['А б,В г','Д е','Ж з'],['Х','Х','Х'],['Алгебра,Физика','Физика,Химия','Алгебра,Химия,Биология'],['а','б','в']],
 sol="anna = set(input().split(','))\nboris = set(input().split(','))\navailable = set(input().split(','))\n\nchosen = anna | boris\nprint(len(chosen & available))\n",
 hint='«Аня или Борис» — объединение `|`. «И есть в университете» — пересечение `&` с третьим множеством.',
 idea='Сначала собираем всех выбранных (объединение), потом оставляем только доступные (пересечение).',
 steps=['Разделитель — запятая без пробела: `.split(",")`. Если написать `split()` без аргумента, названия с пробелами разорвутся.','`anna | boris` — курсы, выбранные хотя бы одним.','`chosen & available` — из них только доступные.','Курс, выбранный обоими, считается один раз: множество не хранит повторов.'],
 mist=['`split()` вместо `split(",")`: «Статистика, Право» превращается в куски.','`&` вместо `|` в первом шаге: получится «выбрали оба».','Сделали сложение множеств через `+` — оно не работает со множествами.']),
dict(n=7, pts=0.75, title='Преподаватели предмета', topics='словарь, перебор ключей',
 text='В окне задан словарь `teachers`: преподаватель → предмет. Вводится название предмета.\n\nНапечатайте фамилии всех преподавателей этого предмета, каждую с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.',
 fin='Одна строка — предмет.', fout='Фамилии по одной на строке или пустой вывод.',
 pre="teachers = {'Иванов': 'математика', 'Петров': 'физика', 'Сидоров': 'математика', 'Кузнецова': 'история', 'Орлов': 'математика'}",
 inputs=[['математика'],['физика'],['химия'],['история'],['Математика']],
 sol="subject = input()\n\nfor teacher in teachers:\n    if teachers[teacher] == subject:\n        print(teacher)\n",
 hint='`for teacher in teachers` перебирает **ключи**. Значение по ключу — `teachers[teacher]`.',
 idea='Перебираем ключи словаря и сравниваем значение с введённым предметом.',
 steps=['`for teacher in teachers:` — на каждом шаге `teacher` это очередной ключ (фамилия).','`teachers[teacher]` — значение по этому ключу, то есть предмет.','Совпало с `subject` — печатаем ключ.','Порядок вывода такой же, как в словаре: Python хранит порядок добавления.'],
 mist=['Печатали `teachers[teacher]` (предмет), а нужен ключ.','Переписали словарь в своём коде: он уже задан, второй раз не нужен (хотя результат не изменится).','Сравнивали регистр: `математика` и `Математика` — разные строки.']),
dict(n=8, pts=1.25, title='Магазины с хорошими месяцами', topics='словарь списков, max',
 text='В окне задан словарь `shops`: магазин → список прибыли за три месяца. Вводится порог.\n\nНапечатайте магазины, у которых **хотя бы в одном месяце** прибыль **строго больше** порога, каждый с новой строки, в порядке словаря.',
 fin='Одна строка — порог (целое число).', fout='Названия магазинов по одному на строке или пустой вывод.',
 pre="shops = {'Бублик': [3000, 4500, 3800], 'Сладкоежка': [5200, 4000, 4100], 'Мёд': [2500, 2700, 2600], 'Пекарня': [6100, 5900, 6000]}",
 inputs=[['5000'],['6100'],['2500'],['4000'],['10000']],
 sol="limit = int(input())\n\nfor shop in shops:\n    if max(shops[shop]) > limit:\n        print(shop)\n",
 hint='«Хотя бы в одном месяце больше порога» — это то же, что «наибольшая прибыль больше порога». Используйте `max`.',
 idea='Вместо перебора месяцев сравниваем с порогом самое большое значение в списке.',
 steps=['`shops[shop]` — список прибыли магазина.','`max(...)` — его наибольший элемент.','Если наибольший больше порога, то хотя бы один месяц подходит. Строго «больше» — это `>`.','Печатаем **ключ** `shop`, а не список.'],
 mist=['Использовали `min` вместо `max`: условие получится другим («во всех месяцах»).','`>=` вместо `>`: при прибыли ровно на пороге магазин напечатается лишним.']),
dict(n=9, pts=1.5, title='Годы одного десятилетия', topics='цикл, целочисленное деление',
 text='Первая строка — годы через пробел. Вторая — начало десятилетия: число, кратное 10 (например, 1990 означает годы с 1990 по 1999 включительно).\n\nНапечатайте, сколько введённых лет входит в это десятилетие.',
 fin='Две строки: годы, начало десятилетия.', fout='Одно число.',
 pre='',
 inputs=[['1990 1995 1989 2000 1999','1990'],['2001 2005 2010','2000'],['1500','1600'],['2020 2021 2022 2029 2030','2020'],['1985 1986','1980']],
 sol="years = input().split()\ndecade = int(input())\n\ncount = 0\nfor year in years:\n    if int(year) // 10 * 10 == decade:\n        count += 1\n\nprint(count)\n",
 hint='Чтобы отбросить последнюю цифру года и вернуть ноль, используйте `год // 10 * 10`. Счётчик создайте до цикла.',
 idea='Для года `y` начало его десятилетия — `y // 10 * 10`. Считаем годы, у которых оно равно введённому.',
 steps=['`years` — список **строк**: каждый год нужен как `int(year)`.','`1995 // 10` даёт 199, умножаем на 10 и получаем 1990 — начало десятилетия.','`count = 0` до цикла, `count += 1` на каждом подходящем.','Печатаем итог после цикла.'],
 mist=['Забыли `int(year)`: `//` со строкой — ошибка.','Счётчик обнулили внутри цикла.','Сравнили `year // 10` с `decade` без умножения на 10: 199 не равно 1990.'],
 trace='`1995`: 1995 // 10 = 199, 199 * 10 = 1990 — подходит для десятилетия 1990. `1989`: 198 * 10 = 1980 — не подходит. `2000`: 2000 — не подходит.'),
dict(n=10, pts=1.5, title='Самый щедрый клиент', topics='while True, словарь-накопитель, максимум',
 text='Вводятся строки вида `клиент,сумма` (сумма — целое число), пока не будет введено слово `END`. Один клиент может встретиться несколько раз.\n\nНайдите клиента с **наибольшей суммарной** суммой чеков. Напечатайте его имя и сумму через пробел. Гарантируется, что есть хотя бы одна строка. Если несколько клиентов с одинаковой максимальной суммой — выведите того, кто встретился в списке раньше.',
 fin='Строки `клиент,сумма`, последняя строка — `END`.', fout='Имя и сумма через пробел.',
 pre='',
 inputs=[['Ира,1000','Олег,600','Ира,6000','Олег,300','Паша,1000','END'],['Аня,5','END'],['А,10','Б,10','END'],['Х,100','У,50','У,60','END'],['Мария,500','Игорь,400','Мария,-200','Игорь,100','END']],
 sol="totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    name, amount = line.split(',')\n    if name in totals:\n        totals[name] += int(amount)\n    else:\n        totals[name] = int(amount)\n\nbest_name = ''\nbest_sum = None\nfor name in totals:\n    if best_sum is None or totals[name] > best_sum:\n        best_sum = totals[name]\n        best_name = name\n\nprint(best_name, best_sum)\n",
 hint='Два шага: (1) в цикле копите суммы в словаре; (2) после цикла найдите максимум. Для строгого сравнения при равных суммах берите `>`, а не `>=`.',
 idea='Сначала собираем словарь «клиент → сумма», потом ищем ключ с наибольшим значением.',
 steps=['`totals = {}` — до цикла.','Если клиент уже есть в словаре, прибавляем: `totals[name] += int(amount)`, иначе создаём запись.','Для максимума нужно стартовое значение. Суммы могут быть отрицательными, поэтому берём `None` и первое же значение его заменяет.','`>` (строго) оставляет первого из равных, как требует условие.','`print(best_name, best_sum)` с запятой печатает через пробел.'],
 mist=['`max(totals)` без `key` берёт максимум **по алфавиту имён**, а не по сумме.','Стартовое значение `0` ломает случай, когда все суммы отрицательные.','`>=` вместо `>`: при равных суммах выберется последний, а не первый.','Забыли `int(...)` у суммы: строки склеиваются (`"1000" + "6000"`).'],
 trace='Ира: 1000, затем 6000 → 7000. Олег: 600, затем 300 → 900. Паша: 1000. Максимум 7000 у Иры. Словарь по шагам: `{Ира: 1000}` → `{Ира: 1000, Олег: 600}` → `{Ира: 7000, Олег: 600}` → …'),
]
